#!/usr/bin/env python3
"""Writes tags.rs: the tag tables of php-src's ext/exif/exif.c.

    python3 -I gen_tags.py <php-src>/ext/exif/exif.c > tags.rs
"""
import re
import sys

src = open(sys.argv[1], encoding="latin-1").read()
out = [
    "//! The tag tables of php-src's ext/exif/exif.c (PHP-3.01), each ending",
    "//! with TAG_TABLE_END's entries. Generated by gen_tags.py; do not edit.",
    "",
    "pub(super) type TagTable = &'static [(u16, &'static str)];",
    "",
]
for m in re.finditer(r"static tag_info_array (tag_table_\w+) = \{(.*?)\n\}\s*;", src, re.S):
    name, body = m.group(1), m.group(2)
    body = re.sub(r"/\*.*?\*/", "", body, flags=re.S)
    entries = []
    for e in re.finditer(r"\{\s*(0x[0-9A-Fa-f]+)\s*,\s*\"((?:[^\"\\]|\\.)*)\"\s*\}", body):
        entries.append((int(e.group(1), 16), e.group(2)))
    if body.count("TAG_TABLE_END") != 1:
        sys.exit(f"{name}: not one TAG_TABLE_END")
    if len({t for t, _ in entries}) != len(entries):
        sys.exit(f"{name}: duplicate tag")
    # TAG_NONE (-1) and TAG_COMPUTED_VALUE (-2) as unsigned short.
    entries += [(0xFFFF, "No tag value"), (0xFFFE, "Computed value")]
    out.append(f"pub(super) const {name.upper()}: TagTable = &[")
    for tag, desc in entries:
        out.append(f'    (0x{tag:04X}, "{desc}"),')
    out.append("];")
    out.append("")
sys.stdout.write("\n".join(out))
